            OPERATOR,
            None,
            None,
            Duration::from_secs(60),
            None,
        )
        .await
        .unwrap();
        *state.0.active_session.lock().await = Some(session.clone());

        let (locked_tx, locked_rx) = oneshot::channel();
        let turn_state = state.clone();
